export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const startsAt = new Date(input.startsAt).getTime();
  const endsAt = new Date(input.endsAt).getTime();
  if (Number.isNaN(startsAt) || Number.isNaN(endsAt) || endsAt <= startsAt) {
    throw new Error("An absence must end after it starts");
