/**
 * Members manage their own absence; managing someone else's takes the same
 * right as changing their role.
 */
function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (member.userId === actor.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

/**
 * Marks a member out of office for `[startsAt, endsAt)`, optionally naming a
 * delegate. Replaces whatever absence the member had.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const startsAt = new Date(input.startsAt).getTime();
  const endsAt = new Date(input.endsAt).getTime();
  if (Number.isNaN(startsAt) || Number.isNaN(endsAt) || endsAt <= startsAt) {
    throw new Error("An absence must end after it starts");
  }

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

