 * consulted.
 */
export async function findActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;

  const instant = at.getTime();
  if (
    instant < new Date(absence.startsAt).getTime() ||
    instant >= new Date(absence.endsAt).getTime()
