  await runOverdueIssueJob(new Date());
  expect((await notes(t.org.id as never, admin as never)).filter((k) => k === "issue_overdue").length).toBe(2);
  expect(await notes(t.org.id as never, member as never)).toEqual([]);
  await commentService.createComment(t.actors.viewer.role === "viewer" ? t.actors.owner : t.actors.owner, { orgId: t.org.id, issueId: own.id, body: "hi", parentId: null, mentionedUserIds: [member, admin] } as never);
  expect((await notes(t.org.id as never, admin as never)).filter((k) => k === "comment_mention").length).toBe(1);
  expect((await notes(t.org.id as never, member as never)).filter((k) => k === "comment_mention").length).toBe(1);
  const adminMember = await memberRepo.findMember(t.org.id, admin);
  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: adminMember!.id });
  expect((await memberService.getAbsence(t.actors.owner, t.org.id, member))?.delegateUserId).toBeNull();
  await expect(memberService.getAbsence(t.actors.owner, t.org.id, admin)).rejects.toBeInstanceOf(NotFoundError);
  await memberService.clearAbsence(t.actors.owner, t.org.id, member);
  await memberService.clearAbsence(t.actors.member, t.org.id, member);
  expect(await memberService.getAbsence(t.actors.owner, t.org.id, member)).toBeNull();
